// 永久消费凭据完整保原出生、会话与本人say；解码只核形状，真实来源必须再走具名只读。
#include "known_personal_dialogue_proof_codec.hpp"
#include "known_personal_dialogue_codec_detail.hpp"
namespace hanmo::resident {namespace {
template<class A>Status identity(A& a,WorldIdentity& v){std::vector<Integer> bytes;if(a.reading())a.sequence("world_id",bytes,[](auto& c,auto& b){return c.field("byte",b);});else a.write_sequence("world_id",v.world_id,[](auto& c,const auto& raw){Integer b=raw;return c.field("byte",b);});if(a.reading()&&a.status().ok){if(bytes.size()!=16)return a.reject("InvalidKnownPersonalDialogueWorld");for(std::size_t i=0;i<16;++i){if(bytes[i]<0||bytes[i]>255)return a.reject("InvalidKnownPersonalDialogueWorld");v.world_id[i]=static_cast<std::uint8_t>(bytes[i]);}}a.field("execution_epoch",v.execution_epoch);a.field("revision",v.revision);return a.field("tick",v.tick);}
template<class A>Status context(A& a,InteractionContext& c){a.field("place_id",c.place_id);a.field("provider_actor_id",c.provider_actor_id);a.field("role_id",c.role_id);a.optional("kind",c.kind,[](auto& x,auto& v){return x.field("value",v);});a.optional("encounter_id",c.encounter_id,[](auto& x,auto& v){return x.field("value",v);});return a.optional("input_error",c.input_error,[](auto& x,auto& v){return x.field("value",v);});}
template<class A>Status proof(A& a,KnownPersonalDialogueProof& p){a.field("opening_fact_id",p.opening_fact_id);a.field("template_id",p.template_id);a.object("declaration",[&](auto& c){c.field("speaker_actor_id",p.declaration.speaker_actor_id);return c.object("meeting",[&](auto& x){auto& m=p.declaration.meeting;x.object("source_identity",[&](auto& y){return identity(y,m.source_identity);});x.field("actor_id",m.actor_id);x.field("provider_actor_id",m.provider_actor_id);x.field("session_id",m.session_id);x.field("dialogue_id",m.dialogue_id);x.field("node_id",m.node_id);x.field("node_kind",m.node_kind);return x.object("context",[&](auto& y){return context(y,m.context);});});});a.object("listener_origin",[&](auto& c){return known_personal_codec::origin(c,p.listener_origin);});return a.object("provider_origin",[&](auto& c){return known_personal_codec::origin(c,p.provider_origin);});}

}
Status emit_known_personal_dialogue_proof_fields(ProjectionWriter&w,const KnownPersonalDialogueProof&p){DynamicProjectionArchive a(w);return proof(a,const_cast<KnownPersonalDialogueProof&>(p));}
BoundaryValue encode_known_personal_dialogue_proof(const KnownPersonalDialogueProof& p){BoundaryValue value;BoundaryProjectionWriter writer(value);auto status=writer.object("",[&](auto&out){return emit_known_personal_dialogue_proof_fields(out,p);});if(status.ok)status=writer.finish();if(!status.ok){boundary::DecodeFailure failure(status.error.original.code,status.error.original.path);failure.error=status.error;throw failure;}return value;}
Outcome<KnownPersonalDialogueProof> decode_known_personal_dialogue_proof(const BoundaryValue& v){auto r=known_personal_codec::unique(v);if(!r.ok)return {false,{},r.error};KnownPersonalDialogueProof p;dynamic_codec::JsonArchive a(v);r=proof(a,p);if(r.ok)r=a.finish();return r.ok?Outcome<KnownPersonalDialogueProof>{true,std::move(p),{}}:Outcome<KnownPersonalDialogueProof>{false,{},r.error};}
Status visit_known_personal_dialogue_proof(CodecVisitor& a,KnownPersonalDialogueProof& p){return proof(a,p);}
Status visit_known_personal_dialogue_proof(dynamic_codec::JsonArchive& a,KnownPersonalDialogueProof& p){return proof(a,p);}
Status visit_known_personal_dialogue_proof(DynamicProjectionArchive& a,KnownPersonalDialogueProof& p){return proof(a,p);}
}
